class Solution {
public:
    int maximumSubtreeSize(vector<vector<int>>& edges, vector<int>& colors) {
        int n = colors.size(), ans = 0;
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        function<pair<bool, int>(int, int)> dfs = [&](int u, int p) -> pair<bool, int> {
            bool good = true;
            int size = 1;
            for (int v : adj[u]) if (v != p) {
                auto child = dfs(v, u);
                good = good && child.first && colors[v] == colors[u];
                size += child.second;
            }
            if (good) ans = max(ans, size);
            return {good, size};
        };
        dfs(0, -1);
        return ans;
    }
};
